mapper.select:
SELECT user_id, u.nickname, r.user_level_val, r.user_level_name, u.agent_id, (select nickname from user_info i where i.id=u.agent_id) as agentName, u.general_agent_id, (select nickname from user_info i where i.id=u.general_agent_id) as generalAgentName, (select count(distinct from_user_id) from user_rebate_detail i where i.user_id = r.user_id and i.settlement_date=r.settlement_date) as rebateMemberCount, ifnull((select sum(performance) from user_rebate_detail i where i.user_id=r.user_id and i.settlement_date=r.settlement_date and from_user_level_val=1), 0) as lv1_performance, ifnull((select sum(rebate_amount) from user_rebate_detail i where i.user_id=r.user_id and i.settlement_date=r.settlement_date and from_user_level_val=1), 0) as lv1_rebate_amount, ifnull((select sum(performance) from user_rebate_detail i where i.user_id=r.user_id and i.settlement_date=r.settlement_date and from_user_level_val=2), 0) as lv2_performance, ifnull((select sum(rebate_amount) from user_rebate_detail i where i.user_id=r.user_id and i.settlement_date=r.settlement_date and from_user_level_val=2), 0) as lv2_rebate_amount, ifnull((select sum(performance) from user_rebate_detail i where i.user_id=r.user_id and i.settlement_date=r.settlement_date and from_user_level_val=3), 0) as lv3_performance, ifnull((select sum(rebate_amount) from user_rebate_detail i where i.user_id=r.user_id and i.settlement_date=r.settlement_date and from_user_level_val=3), 0) as lv3_rebate_amount, ifnull((select sum(performance) from user_rebate_detail i where i.user_id=r.user_id and i.settlement_date=r.settlement_date and from_user_level_val=4), 0) as lv4_performance, ifnull((select sum(rebate_amount) from user_rebate_detail i where i.user_id=r.user_id and i.settlement_date=r.settlement_date and from_user_level_val=4), 0) as lv4_rebate_amount, sum(performance) as totalPerformance, sum(rebate_amount) as totalRebateAmount, settlement_date FROM user_rebate_detail r INNER JOIN user_info u ON r.user_id = u.id where r.is_settlemented = 1
and r.user_id=#{param.userId}
and r.user_level_val=#{param.userLevelVal}
and u.agent_id=#{param.agentId}
and u.general_agent_id=#{param.generalAgentId}
and r.settlement_date>=#{param.startDate}
and r.settlement_date<=#{param.endDate}
group by user_id,u.nickname, r.user_level_val,r.user_level_name,u.agent_id,u.general_agent_id,settlement_date

select tb.*, (select nickname from user_info i where i.id=tb.from_user_agent_id) as fromUserAgentName, (select nickname from user_info i where i.id=tb.from_user_general_agent_id) as fromUserGeneralAgentName from (SELECT user_id, (select nickname from user_info i where i.id=r.user_id) as nickname, r.user_level_val, r.user_level_name, r.from_user_id, (select nickname from user_info i where i.id=r.from_user_id) as from_user_nickname, r.from_user_level_val, r.from_user_level_name, (select agent_id from user_info i where i.id=r.from_user_id) as from_user_agent_id, (select general_agent_id from user_info i where i.id=r.from_user_id) as from_user_general_agent_id, r.performance, r.rebate_ratio, r.rebate_amount, r.settlement_date, r.settlement_date_time, rebate_type, trading_order_sn FROM user_rebate_detail r where r.is_settlemented=1
and r.user_id=#{param.userId}
and r.from_user_id=#{param.fromUserId}
and r.from_user_level_val=#{param.fromUserLevelVal}
and r.settlement_date>=#{param.startDate}
and r.settlement_date<=#{param.endDate}
order by id desc) tb
tb.from_user_agent_id=#{param.fromUserAgentId} and
tb.from_user_general_agent_id=#{param.fromUserGeneralAgentId}
